import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as t,af as e}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"写给仓库的 AGENTS.md","description":"AGENTS.md 是给编码助手的 README。把安装、测试、约定写进仓库，而不是每次对话重说一遍。","frontmatter":{"title":"写给仓库的 AGENTS.md","description":"AGENTS.md 是给编码助手的 README。把安装、测试、约定写进仓库，而不是每次对话重说一遍。","domain":"tech","tags":["prompt"],"navOrder":30,"llm":[15],"prev":{"text":"稳住结构 · JSON","link":"/zh/tech/prompt/json-prompt-best-practices"},"next":{"text":"换模型时改什么","link":"/zh/tech/prompt/official-guide-2026"}},"headers":[],"relativePath":"zh/tech/prompt/agents-doc.md","filePath":"zh/tech/prompt/agents-doc.md","lastUpdated":1788250975000}'),n={name:"zh/tech/prompt/agents-doc.md"};function l(d,s,h,p,o,r){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="写给仓库的-agents-md" tabindex="-1">写给仓库的 AGENTS.md <a class="header-anchor" href="#写给仓库的-agents-md" aria-label="Permalink to &quot;写给仓库的 AGENTS.md&quot;">​</a></h1><p><strong>结论</strong>：对话里反复交代的规矩，应该写进仓库根目录的 <code>AGENTS.md</code>。它是给编码助手的 README，不是另一份给人看的贡献指南。</p><p>上一页把单次提示写清楚。这一页把「对这个仓库永远成立」的部分固化下来。格式来自官方站点 <a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a>，由 Agentic AI Foundation（Linux Foundation）托管，Cursor、Codex、GitHub Copilot、Gemini CLI、Claude Code 等都会读。</p><h2 id="写给谁、不写什么" tabindex="-1">写给谁、不写什么 <a class="header-anchor" href="#写给谁、不写什么" aria-label="Permalink to &quot;写给谁、不写什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>先决条件</strong></td><td>已经会按 <a href="/zh/tech/prompt/">怎么写 Prompt</a> 把任务 / 约束 / 输出写清</td></tr><tr><td><strong>学习目标</strong></td><td>能在本仓库落下一份助手真正会执行的 <code>AGENTS.md</code></td></tr><tr><td><strong>不是本页</strong></td><td>某个产品的完整用法 → <a href="/zh/products/">产品</a>；多 Agent 编排 → <a href="/zh/tech/patterns/agent/">Agent</a></td></tr></tbody></table><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p><code>README.md</code> 写给人：项目是什么、怎么跑起来、怎么贡献。</p><p><code>AGENTS.md</code> 写给助手：装依赖用哪个包管理器、测试怎么跑、哪些目录不能动、提交前必须绿哪些检查。这些话如果写进 README，人会嫌长；如果不写，每个助手都会猜。</p><p>官方原话大意：单独放这个文件，是为了给人看的 README 保持短，同时给助手一个稳定入口。没有必填字段，就是普通 Markdown。冲突时：<strong>离正在改的文件最近的 <code>AGENTS.md</code> 优先</strong>；用户当次对话里的话覆盖一切。</p><h2 id="最小模板" tabindex="-1">最小模板 <a class="header-anchor" href="#最小模板" aria-label="Permalink to &quot;最小模板&quot;">​</a></h2><p>把下面复制到仓库根目录，改成你的命令。本仓库自己的约定也是这一套：根目录只用 <code>pnpm</code>，不要跑 <code>npm install</code>。</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># AGENTS.md</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Setup commands</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 安装依赖：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm install\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（只在仓库根目录）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要在根目录运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`npm install\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 文档开发：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:dev\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 文档构建：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:build\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Code style</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 只用 ES modules（</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`import\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`export\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 根目录有 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`&quot;type&quot;: &quot;module&quot;\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 改文档用中文；代码、提交信息用英文</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Testing instructions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 提交前运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:build\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 改了 PPT 再跑 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm ppt:build\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要只改一页就声称「站点好了」：侧栏链接必须指向真实 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`.md\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Security</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要把 token、本机 MCP 配置、家目录路径写进文档</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 找不到的命令名、flag、URL 标成待核实，不要补「应该是」</span></span></code></pre></div><p>对照 <a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a> 推荐覆盖的块：项目怎么跑、怎么测、代码风格、安全。需要的话再加提交信息、PR 标题、部署步骤。</p><h2 id="工程约定" tabindex="-1">工程约定 <a class="header-anchor" href="#工程约定" aria-label="Permalink to &quot;工程约定&quot;">​</a></h2><ol><li><strong>命令必须是仓库里真能跑的。</strong> 写 <code>pnpm docs:build</code> 之前先跑一遍。助手会执行你列出来的检查。</li><li><strong>写「做什么」，少写人格。</strong> 「你是世界一流的前端专家」几乎不增加可执行信息。包管理器、禁止事项、验收命令才会。</li><li><strong>大 monorepo 用嵌套文件。</strong> 每个包放自己的 <code>AGENTS.md</code>。官方举例：撰写时 OpenAI 主仓库有 88 份。离文件近的那份生效。</li><li><strong>和 README 分工。</strong> README 保留给人的快速开始；助手专属的长约束放到这里。</li><li><strong>迁移旧文件。</strong> 官方建议：<code>mv AGENT.md AGENTS.md &amp;&amp; ln -s AGENTS.md AGENT.md</code>，兼容还在读旧名的工具。</li></ol><p>Gemini CLI 若要显式指定文件名，官方示例是 <code>.gemini/settings.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fileName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AGENTS.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Aider 则在 <code>.aider.conf.yml</code> 写 <code>read: AGENTS.md</code>。多数新工具会默认找根目录这份文件。</p><h2 id="工具怎么读这份文件" tabindex="-1">工具怎么读这份文件 <a class="header-anchor" href="#工具怎么读这份文件" aria-label="Permalink to &quot;工具怎么读这份文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>默认找哪</th><th>还要看什么</th></tr></thead><tbody><tr><td>Cursor</td><td>根目录 / 嵌套 <code>AGENTS.md</code></td><td><code>.cursor/rules</code>、产品页 <a href="/zh/products/cursor/">Cursor</a></td></tr><tr><td>Claude Code</td><td><code>AGENTS.md</code> + <code>CLAUDE.md</code></td><td><a href="/zh/products/claude/claude-code.html">Claude Code</a></td></tr><tr><td>Codex</td><td><code>AGENTS.md</code></td><td><a href="/zh/products/codex/">Codex</a></td></tr><tr><td>GitHub Copilot Coding Agent</td><td><code>AGENTS.md</code></td><td><a href="/zh/products/copilot/">Copilot</a></td></tr><tr><td>Gemini CLI</td><td>默认同名；可在 <code>.gemini/settings.json</code> 指定</td><td>上文配置</td></tr></tbody></table><p>本仓库自己的样本：根目录 <code>AGENTS.md</code>（跨工具）和 <code>Claude.md</code>（Claude Code 补充）。打开对照，不要另抄一份空话。</p><h2 id="坏例子-vs-好例子" tabindex="-1">坏例子 vs 好例子 <a class="header-anchor" href="#坏例子-vs-好例子" aria-label="Permalink to &quot;坏例子 vs 好例子&quot;">​</a></h2><p><strong>坏：</strong> 人格很长，命令是假的。</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是世界一流的全栈专家，代码优雅、测试完备。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">运行 npm test 后再提交。</span></span></code></pre></div><p>本仓根目录跑 <code>npm test</code> 会装错依赖。助手会照做。</p><p><strong>好：</strong> 命令真实、禁区清楚、验收可跑。</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 根目录只用 pnpm。不要 npm install。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 改文档后跑 pnpm docs:build。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要把 token 和本机 MCP 配进文档。</span></span></code></pre></div><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>写成第二份 README。</strong> 重复项目简介，却不写安装和测试命令。</li><li><strong>命令是假的。</strong> 文档里写 <code>npm test</code>，仓库实际是 <code>pnpm test</code>。助手会按错的跑。</li><li><strong>和产品页抢活。</strong> Cursor 规则、Claude Code 的 <code>CLAUDE.md</code> 仍以各产品文档为准。<code>AGENTS.md</code> 是跨工具最小公约数。</li><li><strong>指望它替代当次任务。</strong> 「把设置页对比度修掉」写在对话里。<code>AGENTS.md</code> 不管这一次改哪个文件。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>换模型后提示行为飘了 → <a href="/zh/tech/prompt/official-guide-2026.html">换模型时改什么</a></li><li>提示要变成可复用技能 → <a href="/zh/tech/skills/claude-skills-overview.html">Skills</a></li><li>要助手调浏览器 / 工单 / 文档 → <a href="/zh/tech/mcp/mcp-course-notes.html">MCP</a></li></ul><h2 id="深读" tabindex="-1">深读 <a class="header-anchor" href="#深读" aria-label="Permalink to &quot;深读&quot;">​</a></h2><ul><li>官方格式与示例：<a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a></li><li>示例仓库检索：GitHub 搜索 <code>filename:AGENTS.md</code>（官方称已有 6 万+ 项目采用）</li><li>本仓库根目录的 <code>AGENTS.md</code> / <code>Claude.md</code>：同一套约定的实地样本</li></ul>`,33)])])}const u=i(n,[["render",l]]);export{m as __pageData,u as default};
